%% Fig4_PreC_TemporalMemory_Horizon_Audit.m
% =========================================================================
% Pre-Fig.4C diagnostic:
%   A) Does the CIR/GammaOU mesoscopic ordering depend on the chosen
%      lipid-damage memory time tau_L / the 10-min window?
%   B) Is Tobs = 60 min a stable observation horizon for the mesoscopic FPT?
%
% This script is POST-PROCESSING ONLY. It loads the FINAL Fig.4B MAT file
% generated by:
%   Fig4B_MesoscopicFateRoutes_FINAL_FIXED_v6_decoupled...
%
% No TD-CME or SD-RDME trajectory is regenerated.
%
% IMPORTANT separation of time scales
% -----------------------------------
%   Tobs  : observation horizon (how long the experiment is watched)
%   tau_L : cellular lipid-damage memory / repair time
%
% They are not the same parameter and should not be varied interchangeably.
%
% For the tau_L scan, rho_L = 1/tau_L is changed, BUT the reference
% operating point is re-anchored so that the ACTUAL mean CU drive remains:
%
%     E[U_CU] / Ucrit(tau_L) = meanDriveOverCritical
%
% with eta = omega_S/omega_T kept fixed.
%
% This isolates memory-time effects from the trivial fact that changing
% rho_L otherwise changes the deterministic commitment threshold.
%
% =========================================================================
clear; close all; clc;

%% ------------------------------ User input -------------------------------
DATA_NAME = 'Fig4B_fateRoutes_data.mat';

% Sliding-window audit: directly asks whether "10 min" matters.
windowList_min = [1 2 5 10 15 20 30 45 60];

% Decoder memory scan. Include tau > Tobs to approach a dose-integrating
% limit over the 60-min experiment.
tauList_min = [1 2 5 10 20 40 60 120];

% Observation-horizon robustness that can be obtained WITHOUT rerunning the
% microscopic models. Values must be <= the saved source horizon.
TobsList_min = [20 30 45 60];

nBoot = 1000;
seedBoot = 20260831;
alphaCI = 0.05;

SAVE_FIG = true;
SAVE_CSV = true;
EXPORT_DPI = 600;

%% ------------------------------ Load data --------------------------------
scriptDir = fileparts(mfilename('fullpath'));
if isempty(scriptDir), scriptDir = pwd; end
dataFile = resolveInputFile(scriptDir,DATA_NAME);
if isempty(dataFile)
    error('Cannot find %s. Put this script beside the FINAL Fig4B data MAT.',DATA_NAME);
end
D = load(dataFile);

required = {'meta','inputs','R'};
for k=1:numel(required)
    if ~isfield(D,required{k}), error('Missing variable %s in MAT.',required{k}); end
end

IT_C = D.inputs.IT_C;
IT_G = D.inputs.IT_G;
IS_U = D.inputs.IS_U;
IS_F = D.inputs.IS_F;

if isfield(D.inputs,'idxT_pair')
    idxT = D.inputs.idxT_pair(:);
else
    idxT = balancedSourceIndices(size(IT_C,1),size(IT_C,1),20260825);
end
if isfield(D.inputs,'idxS_pair')
    idxS = D.inputs.idxS_pair(:);
else
    idxS = balancedSourceIndices(size(IS_U,1),numel(idxT),20260826);
end

dt = D.meta.dtBin_min;
Tsource = D.meta.Tobs_min;
meso0 = D.meta.meso;

if max(TobsList_min)>Tsource+1e-12
    error('This file only contains %.1f min source paths. Horizon scan must be <= that.',Tsource);
end

outDir = fullfile(scriptDir,'Fig4_PreC_temporal_horizon_audit');
if ~exist(outDir,'dir'), mkdir(outDir); end

%% ====================== A. Sliding-window audit ==========================
% For each TD trajectory, compute the largest dose accumulated in a window
% of length w.  This does not invoke the LPO model, so it is the cleanest
% direct test of whether the apparent ordering is window-scale dependent.

nTD = size(IT_C,1);
nW = numel(windowList_min);

ratioWin = nan(nW,1);
ratioWinCI = nan(nW,2);
meanCWin = nan(nW,1);
meanGWin = nan(nW,1);

rng(seedBoot,'twister');
bootIdx = randi(nTD,nTD,nBoot);

for iw=1:nW
    w = windowList_min(iw);
    c = maxWindowDose(IT_C,dt,w);
    g = maxWindowDose(IT_G,dt,w);

    meanCWin(iw)=mean(c);
    meanGWin(iw)=mean(g);
    ratioWin(iw)=mean(g)/max(mean(c),eps);

    rb=zeros(nBoot,1);
    for b=1:nBoot
        ii=bootIdx(:,b);
        rb(b)=mean(g(ii))/max(mean(c(ii)),eps);
    end
    ratioWinCI(iw,:)=quantileLocal(rb,[alphaCI/2 1-alphaCI/2]);
end

%% ======================== B. tau_L decoder scan ==========================
% Re-anchor the operating point at every tau:
%   mean U_CU / Ucrit = fixed target
% so that changes are caused by memory time, not by changing distance to the
% deterministic threshold.

nTau=numel(tauList_min);
meanITC=mean(IT_C(:));
meanISU=mean(IS_U(:));
eta=meso0.eta_ST;
target=meso0.meanDriveOverCritical;
ML=meso0.ML;
L0=meso0.L0;

tauOut = struct();
tauOut.tau=tauList_min(:);
tauOut.Hratio=nan(nTau,1);
tauOut.HratioCI=nan(nTau,2);
tauOut.PT_C=nan(nTau,1);
tauOut.PT_G=nan(nTau,1);
tauOut.RMST_T_C=nan(nTau,1);
tauOut.RMST_T_G=nan(nTau,1);
tauOut.RMST_CU=nan(nTau,1);
tauOut.RMST_GU=nan(nTau,1);
tauOut.RMST_CF=nan(nTau,1);
tauOut.RMST_GF=nan(nTau,1);
tauOut.P_CU=nan(nTau,1);
tauOut.P_GU=nan(nTau,1);
tauOut.P_CF=nan(nTau,1);
tauOut.P_GF=nan(nTau,1);
tauOut.Joint_CU=nan(nTau,1);
tauOut.Joint_GU=nan(nTau,1);
tauOut.Joint_CF=nan(nTau,1);
tauOut.Joint_GF=nan(nTau,1);
tauOut.omegaT=nan(nTau,1);
tauOut.omegaS=nan(nTau,1);

% Pair source banks using the same independent pairing as FINAL Fig.4B.
ITCp=IT_C(idxT,:);
ITGp=IT_G(idxT,:);
ISUp=IS_U(idxS,:);
ISFp=IS_F(idxS,:);

rng(seedBoot+1,'twister');
bootTD = randi(nTD,nTD,nBoot);

for itau=1:nTau
    tau=tauList_min(itau);
    rho=1/tau;
    Ucrit=rho*ML/(1-ML);

    % Exact actual-CU re-anchoring.
    omegaT=target*Ucrit/(meanITC + eta*meanISU);
    omegaS=eta*omegaT;
    tauOut.omegaT(itau)=omegaT;
    tauOut.omegaS(itau)=omegaS;

    HC = memoryPeak(IT_C,dt,tau);
    HG = memoryPeak(IT_G,dt,tau);
    tauOut.Hratio(itau)=mean(HG)/max(mean(HC),eps);

    rb=zeros(nBoot,1);
    for b=1:nBoot
        ii=bootTD(:,b);
        rb(b)=mean(HG(ii))/max(mean(HC(ii)),eps);
    end
    tauOut.HratioCI(itau,:)=quantileLocal(rb,[alphaCI/2 1-alphaCI/2]);

    meso=meso0;
    meso.tauL_min=tau;
    meso.rhoL=rho;
    meso.omegaT=omegaT;
    meso.omegaS=omegaS;

    % T-only decoder.
    fC=propagateLPOExact(omegaT*IT_C,rho,ML,L0,dt,Tsource);
    fG=propagateLPOExact(omegaT*IT_G,rho,ML,L0,dt,Tsource);
    tauOut.PT_C(itau)=mean(fC<=Tsource);
    tauOut.PT_G(itau)=mean(fG<=Tsource);
    tauOut.RMST_T_C(itau)=mean(min(fC,Tsource));
    tauOut.RMST_T_G(itau)=mean(min(fG,Tsource));

    % Full four backgrounds.
    Rtau=evaluateFourBackgrounds(ITCp,ITGp,ISUp,ISFp,meso,dt,Tsource);
    tauOut.RMST_CU(itau)=Rtau(1).RMST60;
    tauOut.RMST_GU(itau)=Rtau(2).RMST60;
    tauOut.RMST_CF(itau)=Rtau(3).RMST60;
    tauOut.RMST_GF(itau)=Rtau(4).RMST60;
    tauOut.P_CU(itau)=Rtau(1).Pcross60;
    tauOut.P_GU(itau)=Rtau(2).Pcross60;
    tauOut.P_CF(itau)=Rtau(3).Pcross60;
    tauOut.P_GF(itau)=Rtau(4).Pcross60;
    tauOut.Joint_CU(itau)=Rtau(1).routeFrac(4);
    tauOut.Joint_GU(itau)=Rtau(2).routeFrac(4);
    tauOut.Joint_CF(itau)=Rtau(3).routeFrac(4);
    tauOut.Joint_GF(itau)=Rtau(4).routeFrac(4);
end

%% ===================== C. Observation-horizon audit ======================
% Uses the already-computed FINAL FPTs. This tests whether 60 min is a
% pathological endpoint. It does not alter tau_L.

R0=D.R;
nH=numel(TobsList_min);
P_H=zeros(nH,4);
RMST_H=zeros(nH,4);
Joint_H=zeros(nH,4);
Resist_H=zeros(nH,4);

for ih=1:nH
    H=TobsList_min(ih);
    for c=1:4
        FT=R0(c).FPT_T;
        FS=R0(c).FPT_S;
        FTS=R0(c).FPT_TS;

        P_H(ih,c)=mean(FTS<=H);
        RMST_H(ih,c)=mean(min(FTS,H));

        crossT=FT<=H;
        crossS=FS<=H;
        crossTS=FTS<=H;
        joint=(~crossT & ~crossS & crossTS);
        resistant=~crossTS;
        Joint_H(ih,c)=mean(joint);
        Resist_H(ih,c)=mean(resistant);
    end
end

%% =============================== Figures =================================
set(groot,'defaultFigureColor','w');
set(groot,'defaultAxesFontName','Arial');
set(groot,'defaultTextFontName','Arial');

% Figure 1: time-scale dependence.
fig1=figure('Units','centimeters','Position',[1 2 18.3 6.0],'Color','w');
tl=tiledlayout(fig1,1,3,'TileSpacing','compact','Padding','compact');

ax1=nexttile; hold on;
errorbar(windowList_min,ratioWin,ratioWin-ratioWinCI(:,1),ratioWinCI(:,2)-ratioWin, ...
    'o-','Color',[0.18 0.18 0.18],'MarkerFaceColor','w','LineWidth',1.1,'CapSize',4);
yline(1,':','Color',[0.55 0.55 0.55]);
xline(10,':','Color',[0.70 0.70 0.70]);
xlabel('Sliding-window length, w (min)');
ylabel('GammaOU / CIR');
title('Maximum temporal-window dose','FontWeight','normal');
formatAxes(ax1);

ax2=nexttile; hold on;
errorbar(tauList_min,tauOut.Hratio, ...
    tauOut.Hratio-tauOut.HratioCI(:,1),tauOut.HratioCI(:,2)-tauOut.Hratio, ...
    'o-','Color',[0.18 0.18 0.18],'MarkerFaceColor','w','LineWidth',1.1,'CapSize',4);
yline(1,':','Color',[0.55 0.55 0.55]);
xline(10,':','Color',[0.70 0.70 0.70]);
set(ax2,'XScale','log');
xlabel('Lipid-damage memory, \tau_L (min)');
ylabel('H_{max}^{GammaOU} / H_{max}^{CIR}');
title('Finite-memory path decoding','FontWeight','normal');
formatAxes(ax2);

ax3=nexttile; hold on;
plot(tauList_min,tauOut.RMST_GU-tauOut.RMST_CU,'o-', ...
    'Color',[0.80 0.34 0.27],'LineWidth',1.2,'MarkerFaceColor','w');
plot(tauList_min,tauOut.RMST_GF-tauOut.RMST_CF,'s--', ...
    'Color',[0.48 0.24 0.62],'LineWidth',1.2,'MarkerFaceColor','w');
yline(0,':','Color',[0.55 0.55 0.55]);
xline(10,':','Color',[0.70 0.70 0.70]);
set(ax3,'XScale','log');
xlabel('Lipid-damage memory, \tau_L (min)');
ylabel('\DeltaRMST_{G-C} (min)');
title('Fate-ordering dependence on memory','FontWeight','normal');
legend({'Uniform background','Full background'},'Box','off','Location','best','FontSize',7);
formatAxes(ax3);

if SAVE_FIG
    exportgraphics(fig1,fullfile(outDir,'TemporalMemory_Scan.png'),'Resolution',EXPORT_DPI);
    exportgraphics(fig1,fullfile(outDir,'TemporalMemory_Scan.pdf'),'ContentType','vector');
end

% Figure 2: observation-horizon robustness.
fig2=figure('Units','centimeters','Position',[1 2 18.3 6.0],'Color','w');
tl2=tiledlayout(fig2,1,3,'TileSpacing','compact','Padding','compact');

cols=[0.38 0.40 0.43;0.82 0.32 0.24;0.16 0.43 0.70;0.48 0.24 0.62];
names={'CU','GU','CF','GF'};

ax=nexttile; hold on;
for c=1:4, plot(TobsList_min,P_H(:,c),'o-','Color',cols(c,:),'LineWidth',1.2); end
xlabel('Observation horizon, T_{obs} (min)');
ylabel('P(commitment by T_{obs})');
title('Commitment probability','FontWeight','normal');
legend(names,'Box','off','Location','northwest','FontSize',7); formatAxes(ax);

ax=nexttile; hold on;
for c=1:4, plot(TobsList_min,RMST_H(:,c),'o-','Color',cols(c,:),'LineWidth',1.2); end
xlabel('Observation horizon, T_{obs} (min)');
ylabel('RMST_{Tobs} (min)');
title('Restricted mean time','FontWeight','normal'); formatAxes(ax);

ax=nexttile; hold on;
for c=1:4, plot(TobsList_min,Joint_H(:,c),'o-','Color',cols(c,:),'LineWidth',1.2); end
xlabel('Observation horizon, T_{obs} (min)');
ylabel('Joint-required fraction');
title('Route-composition robustness','FontWeight','normal'); formatAxes(ax);

if SAVE_FIG
    exportgraphics(fig2,fullfile(outDir,'ObservationHorizon_Scan.png'),'Resolution',EXPORT_DPI);
    exportgraphics(fig2,fullfile(outDir,'ObservationHorizon_Scan.pdf'),'ContentType','vector');
end

%% ================================ Export =================================
windowTable=table(windowList_min(:),meanCWin,meanGWin,ratioWin, ...
    ratioWinCI(:,1),ratioWinCI(:,2), ...
    'VariableNames',{'Window_min','MeanMaxDose_CIR','MeanMaxDose_GammaOU', ...
    'GoverC','GoverC_CI_L','GoverC_CI_U'});

tauTable=struct2table(tauOut);

hRows=[];
for ih=1:nH
    for c=1:4
        hRows=[hRows; table(TobsList_min(ih),string(names{c}), ...
            P_H(ih,c),RMST_H(ih,c),Joint_H(ih,c),Resist_H(ih,c), ...
            'VariableNames',{'Tobs_min','Condition','Pcommit','RMST','JointFrac','ResistantFrac'})]; %#ok<AGROW>
    end
end

if SAVE_CSV
    writetable(windowTable,fullfile(outDir,'SlidingWindow_Audit.csv'));
    writetable(tauTable,fullfile(outDir,'TauL_Decoder_Audit.csv'));
    writetable(hRows,fullfile(outDir,'ObservationHorizon_Audit.csv'));
end

fprintf('\n=== Key audit outputs ===\n');
fprintf('At w=10 min, max-window Gamma/CIR = %.4f\n',ratioWin(windowList_min==10));
fprintf('At w=60 min, max-window Gamma/CIR = %.4f\n',ratioWin(windowList_min==60));
[~,i10]=min(abs(tauList_min-10));
fprintf('At tau_L=10 min, Hmax Gamma/CIR = %.4f\n',tauOut.Hratio(i10));
fprintf('At tau_L=10 min, Delta RMST_G-C (U) = %.4f min\n', ...
    tauOut.RMST_GU(i10)-tauOut.RMST_CU(i10));
fprintf('Outputs saved in: %s\n',outDir);

%% ============================= Local functions ============================
function path=resolveInputFile(scriptDir,name)
    cands = {fullfile(pwd,name),fullfile(scriptDir,name), ...
        fullfile(scriptDir,'Fig4B_fate_routes_final',name)};
    path='';
    for k=1:numel(cands)
        if isfile(cands{k}), path=cands{k}; return; end
    end
end

function m=maxWindowDose(I,dt,w)
    nWin=max(1,round(w/dt));
    [n,nBins]=size(I);
    if nWin>=nBins
        m=sum(I,2)*dt;
        return;
    end
    cs=[zeros(n,1),cumsum(I,2)*dt];
    W=cs(:,nWin+1:nBins+1)-cs(:,1:nBins+1-nWin);
    m=max(W,[],2);
end

function Hmax=memoryPeak(I,dt,tau)
    decay=exp(-dt/tau);
    gain=tau*(1-decay);
    H=zeros(size(I,1),1);
    Hmax=zeros(size(I,1),1);
    for b=1:size(I,2)
        H=decay*H+gain*I(:,b);
        Hmax=max(Hmax,H);
    end
end

function R=evaluateFourBackgrounds(IT_C,IT_G,IS_U,IS_F,meso,dt,Tobs)
    UT_C=meso.omegaT*IT_C; UT_G=meso.omegaT*IT_G;
    US_U=meso.omegaS*IS_U; US_F=meso.omegaS*IS_F;

    FTC=propagateLPOExact(UT_C,meso.rhoL,meso.ML,meso.L0,dt,Tobs);
    FTG=propagateLPOExact(UT_G,meso.rhoL,meso.ML,meso.L0,dt,Tobs);
    FSU=propagateLPOExact(US_U,meso.rhoL,meso.ML,meso.L0,dt,Tobs);
    FSF=propagateLPOExact(US_F,meso.rhoL,meso.ML,meso.L0,dt,Tobs);

    FCU=propagateLPOExact(UT_C+US_U,meso.rhoL,meso.ML,meso.L0,dt,Tobs);
    FGU=propagateLPOExact(UT_G+US_U,meso.rhoL,meso.ML,meso.L0,dt,Tobs);
    FCF=propagateLPOExact(UT_C+US_F,meso.rhoL,meso.ML,meso.L0,dt,Tobs);
    FGF=propagateLPOExact(UT_G+US_F,meso.rhoL,meso.ML,meso.L0,dt,Tobs);

    R(1)=assemble(FTC,FSU,FCU,Tobs);
    R(2)=assemble(FTG,FSU,FGU,Tobs);
    R(3)=assemble(FTC,FSF,FCF,Tobs);
    R(4)=assemble(FTG,FSF,FGF,Tobs);
end

function R=assemble(FT,FS,FTS,Tobs)
    cT=FT<=Tobs; cS=FS<=Tobs; cTS=FTS<=Tobs;
    rc=zeros(size(FTS));
    rc(cT & ~cS)=1;
    rc(~cT & cS)=2;
    rc(cT & cS)=3;
    rc(~cT & ~cS & cTS)=4;
    rc(~cTS)=5;
    R.FPT_T=FT; R.FPT_S=FS; R.FPT_TS=FTS;
    R.routeCode=rc;
    R.routeFrac=arrayfun(@(x)mean(rc==x),1:5);
    R.Pcross60=mean(cTS);
    R.RMST60=mean(min(FTS,Tobs));
end

function FPT=propagateLPOExact(U,rho,ML,L0,dt,Tobs)
    n=size(U,1); nBins=size(U,2);
    L=L0*ones(n,1); FPT=inf(n,1);
    for b=1:nBins
        Ub=max(U(:,b),0); a=Ub+rho;
        Lnext=L;
        aa=a>eps;
        if any(aa)
            av=a(aa); uv=Ub(aa); Lss=uv./av;
            E=exp(-av*dt);
            Lnext(aa)=Lss+(L(aa)-Lss).*E;
        end
        Lnext=min(max(Lnext,0),1);
        cross=isinf(FPT)&(L<ML)&(Lnext>=ML);
        if any(cross)
            ii=find(cross); av=a(ii); uv=Ub(ii); Lss=uv./av;
            ratio=(ML-Lss)./(L(ii)-Lss);
            ratio=max(min(ratio,1),realmin);
            tc=-log(ratio)./av;
            tc=max(min(tc,dt),0);
            FPT(ii)=(b-1)*dt+tc;
        end
        L=Lnext;
    end
    FPT(FPT>Tobs)=inf;
end

function idx=balancedSourceIndices(nBank,nPairs,seed)
    rng(seed,'twister'); idx=zeros(nPairs,1); pos=1;
    while pos<=nPairs
        p=randperm(nBank); take=min(nBank,nPairs-pos+1);
        idx(pos:pos+take-1)=p(1:take); pos=pos+take;
    end
end

function q=quantileLocal(x,p)
    x=sort(x(:)); n=numel(x); p=p(:).'; q=nan(size(p));
    for j=1:numel(p)
        pos=1+min(max(p(j),0),1)*(n-1); lo=floor(pos); hi=ceil(pos);
        if lo==hi, q(j)=x(lo);
        else, q(j)=x(lo)+(pos-lo)*(x(hi)-x(lo)); end
    end
end

function formatAxes(ax)
    set(ax,'Box','on','LineWidth',0.7,'TickDir','out','Layer','top', ...
        'FontName','Arial','FontSize',7);
end
